// O mapa mínimo: centro em Brasília, zoom 4, camada do OpenStreetMap.
const mapa = L.map('mapa').setView([-15.78, -47.93], 4);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
  attribution: '© OpenStreetMap contributors'
}).addTo(mapa);

// Carrega um GeoJSON e colore cada feição pelo valor de um dado.
fetch('bairros.geojson')
  .then(r => r.json())
  .then(g => L.geoJSON(g, {
    style: f => ({ fillColor: cor(f.properties.valor), weight: 1, fillOpacity: 0.7 })
  }).addTo(mapa));
// 'cor' deve mapear o valor em 4-6 classes; some uma legenda explicando as faixas.
